/**
 * SyntaxArena Battlestation Engine
 * Client-side customization coordinator for mechanical keyboard audio synthesis,
 * CRT phosphor monitor shaders, and RGB chassis illumination.
 * Spec: docs/ARCHITECTURE.md, docs/GAME_RULES.md
 */


const BATTLESTATION_STORAGE_KEY = 'syntaxarena_battlestation_loadout';

var BattlestationEngine = window.BattlestationEngine = {
  loadout: {
    keyboardSwitch: 'switch_cherry_blue',
    crtShader: 'crt_none',
    rgbUnderglow: 'rgb_none',
    unlockedUpgrades: []
  },
  audioCtx: null,
  matrixCanvas: null,
  matrixAnimId: null,

  /**
   * Initialize battlestation engine, restore saved loadout, and apply cosmetics to DOM.
   */
  init() {
    this.loadSavedLoadout();
    if (typeof document !== 'undefined') {
      this.applyCosmetics();
    }
    return this.getSnapshot();
  },

  /**
   * Restore saved loadout from localStorage.
   */
  loadSavedLoadout() {
    try {
      if (typeof localStorage !== 'undefined') {
        const raw = localStorage.getItem(BATTLESTATION_STORAGE_KEY);
        if (raw) {
          const parsed = JSON.parse(raw);
          this.loadout = {
            keyboardSwitch: parsed.keyboardSwitch || 'switch_cherry_blue',
            crtShader: parsed.crtShader || 'crt_none',
            rgbUnderglow: parsed.rgbUnderglow || 'rgb_none',
            unlockedUpgrades: Array.isArray(parsed.unlockedUpgrades) ? parsed.unlockedUpgrades : []
          };
        }
      }
    } catch (e) {
      console.warn('[BattlestationEngine] Storage access restricted. Using default loadout.');
    }
    return this.loadout;
  },

  /**
   * Save active loadout to localStorage.
   */
  saveLoadout() {
    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem(BATTLESTATION_STORAGE_KEY, JSON.stringify(this.loadout));
      }
    } catch (e) {
      // In-memory fallback
    }
  },

  /**
   * Get current loadout snapshot.
   */
  getSnapshot() {
    return {
      loadout: { ...this.loadout },
      equippedSwitch: BattlestationCatalog.getItemById(this.loadout.keyboardSwitch),
      equippedShader: BattlestationCatalog.getItemById(this.loadout.crtShader),
      equippedUnderglow: BattlestationCatalog.getItemById(this.loadout.rgbUnderglow),
      unlockedUpgrades: [...this.loadout.unlockedUpgrades]
    };
  },

  /**
   * Check if a customization item is unlocked for a given player XP.
   * @param {string} itemId
   * @param {number} userXP
   */
  isUnlocked(itemId, userXP = 0) {
    const item = BattlestationCatalog.getItemById(itemId);
    if (!item) return false;
    if (item.requiredXP === 0) return true;
    if (this.loadout.unlockedUpgrades.includes(itemId)) return true;
    return (userXP || 0) >= item.requiredXP;
  },

  /**
   * Equip an item in a specific category.
   * @param {'keyboardSwitch'|'crtShader'|'rgbUnderglow'|'hardware'} category
   * @param {string} itemId
   * @param {number} userXP
   */
  equip(category, itemId, userXP = 0) {
    const item = BattlestationCatalog.getItemById(itemId);
    if (!item) {
      return { success: false, message: `Item "${itemId}" not found in catalog.` };
    }

    if (!this.isUnlocked(itemId, userXP)) {
      return {
        success: false,
        message: `Locked! Requires ${item.requiredXP.toLocaleString()} XP to unlock.`
      };
    }

    if (category === 'hardware') {
      if (!this.loadout.unlockedUpgrades.includes(itemId)) {
        this.loadout.unlockedUpgrades.push(itemId);
      }
    } else if (category === 'keyboard' || category === 'keyboardSwitch') {
      this.loadout.keyboardSwitch = itemId;
    } else if (category === 'crt' || category === 'crtShader') {
      this.loadout.crtShader = itemId;
    } else if (category === 'rgb' || category === 'rgbUnderglow') {
      this.loadout.rgbUnderglow = itemId;
    }

    this.saveLoadout();
    this.applyCosmetics();

    return {
      success: true,
      loadout: { ...this.loadout },
      message: `Equipped ${item.name}!`
    };
  },

  /**
   * Apply CRT shaders, RGB underglow, and hardware perks to the DOM.
   */
  applyCosmetics() {
    if (typeof document === 'undefined') return;

    const root = document.body;
    if (!root) return;

    // 1. Remove all previous CRT shader classes
    const allShaders = BattlestationCatalog.getShaders();
    allShaders.forEach(s => {
      if (s.cssClass) root.classList.remove(s.cssClass);
    });

    // Apply active CRT shader class
    const activeShader = BattlestationCatalog.getItemById(this.loadout.crtShader);
    if (activeShader && activeShader.cssClass) {
      root.classList.add(activeShader.cssClass);
    }

    // 2. Remove all previous RGB underglow classes
    const allUnderglows = BattlestationCatalog.getUnderglows();
    allUnderglows.forEach(u => {
      if (u.cssClass) root.classList.remove(u.cssClass);
    });

    // Apply active RGB underglow class
    const activeUnderglow = BattlestationCatalog.getItemById(this.loadout.rgbUnderglow);
    if (activeUnderglow && activeUnderglow.cssClass) {
      root.classList.add(activeUnderglow.cssClass);
    }

    // 3. Matrix Rain Background Hardware Perk
    const hasMatrixPerk = this.loadout.unlockedUpgrades.includes('rig_matrix_rain');
    this._toggleMatrixRain(hasMatrixPerk);
  },

  /**
   * Lazy-initialize AudioContext for procedural mechanical switch synthesis.
   */
  _ensureAudioContext() {
    if (typeof window === 'undefined') return null;
    if (!this.audioCtx) {
      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (AudioContextClass) {
        try {
          this.audioCtx = new AudioContextClass();
        } catch (_) {
          this.audioCtx = null;
        }
      }
    }
    if (this.audioCtx && this.audioCtx.state === 'suspended') {
      this.audioCtx.resume().catch(() => {});
    }
    return this.audioCtx;
  },

  /**
   * Synthesize tactile audio for mechanical keypress or click.
   * @param {string} [switchId] Specific switch or active equipped switch
   * @param {number} [volumeScale=1.0] Master volume scale multiplier (0.0 to 1.0)
   */
  playSwitchSound(switchId = null, volumeScale = 1.0) {
    if (volumeScale <= 0) return;
    const id = switchId || this.loadout.keyboardSwitch;
    const item = BattlestationCatalog.getItemById(id);
    if (!item || !item.synthProfile) return;

    const ctx = this._ensureAudioContext();
    if (!ctx) return;

    const now = ctx.currentTime;
    const p = item.synthProfile;
    const v = Math.max(0, Math.min(1, volumeScale));

    try {
      if (p.type === 'blue') {
        // High crisp snap + snappy bottom-out
        const snapOsc = ctx.createOscillator();
        const snapGain = ctx.createGain();
        snapOsc.type = 'triangle';
        snapOsc.frequency.setValueAtTime(p.clickFreq, now);
        snapOsc.frequency.exponentialRampToValueAtTime(800, now + p.clickDuration);
        snapGain.gain.setValueAtTime(0.35 * v, now);
        snapGain.gain.exponentialRampToValueAtTime(0.001, now + p.clickDuration);
        snapOsc.connect(snapGain);
        snapGain.connect(ctx.destination);
        snapOsc.start(now);
        snapOsc.stop(now + p.clickDuration);

        // Plastic bottom-out resonance
        const thudOsc = ctx.createOscillator();
        const thudGain = ctx.createGain();
        thudOsc.type = 'sine';
        thudOsc.frequency.setValueAtTime(p.resonanceFreq, now + 0.008);
        thudOsc.frequency.exponentialRampToValueAtTime(150, now + p.resonanceDuration);
        thudGain.gain.setValueAtTime(0.2 * v, now + 0.008);
        thudGain.gain.exponentialRampToValueAtTime(0.001, now + p.resonanceDuration);
        thudOsc.connect(thudGain);
        thudGain.connect(ctx.destination);
        thudOsc.start(now + 0.008);
        thudOsc.stop(now + p.resonanceDuration);

      } else if (p.type === 'brown') {
        // Dampened tactile bump & muted thud
        const thudOsc = ctx.createOscillator();
        const thudGain = ctx.createGain();
        thudOsc.type = 'sine';
        thudOsc.frequency.setValueAtTime(p.clickFreq, now);
        thudOsc.frequency.exponentialRampToValueAtTime(180, now + p.resonanceDuration);
        thudGain.gain.setValueAtTime(0.25 * v, now);
        thudGain.gain.exponentialRampToValueAtTime(0.001, now + p.resonanceDuration);
        thudOsc.connect(thudGain);
        thudGain.connect(ctx.destination);
        thudOsc.start(now);
        thudOsc.stop(now + p.resonanceDuration);

      } else if (p.type === 'buckling') {
        // Hollow chassis clack + metallic spring ping
        const clackOsc = ctx.createOscillator();
        const clackGain = ctx.createGain();
        clackOsc.type = 'square';
        clackOsc.frequency.setValueAtTime(p.resonanceFreq, now);
        clackOsc.frequency.exponentialRampToValueAtTime(120, now + p.resonanceDuration);
        clackGain.gain.setValueAtTime(0.2 * v, now);
        clackGain.gain.exponentialRampToValueAtTime(0.001, now + p.resonanceDuration);
        clackOsc.connect(clackGain);
        clackGain.connect(ctx.destination);
        clackOsc.start(now);
        clackOsc.stop(now + p.resonanceDuration);

        // Metallic spring ring
        const ringOsc = ctx.createOscillator();
        const ringGain = ctx.createGain();
        ringOsc.type = 'sine';
        ringOsc.frequency.setValueAtTime(p.metallicRingFreq || 3900, now + 0.004);
        ringOsc.frequency.linearRampToValueAtTime(3200, now + 0.06);
        ringGain.gain.setValueAtTime(0.12 * v, now + 0.004);
        ringGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.07);
        ringOsc.connect(ringGain);
        ringGain.connect(ctx.destination);
        ringOsc.start(now + 0.004);
        ringOsc.stop(now + 0.07);

      } else if (p.type === 'haptic') {
        // Sci-Fi sub-bass drop with neon blip
        const hapticOsc = ctx.createOscillator();
        const hapticGain = ctx.createGain();
        hapticOsc.type = 'sine';
        hapticOsc.frequency.setValueAtTime(p.startFreq || 240, now);
        hapticOsc.frequency.exponentialRampToValueAtTime(p.endFreq || 45, now + p.clickDuration);
        hapticGain.gain.setValueAtTime(0.4 * v, now);
        hapticGain.gain.exponentialRampToValueAtTime(0.001, now + p.clickDuration);
        hapticOsc.connect(hapticGain);
        hapticGain.connect(ctx.destination);
        hapticOsc.start(now);
        hapticOsc.stop(now + p.clickDuration);
      }
    } catch (err) {
      // Audio playback suppressed safely
    }
  },

  /**
   * Preview a switch sound by ID.
   * @param {string} switchId
   */
  previewSwitch(switchId) {
    this.playSwitchSound(switchId);
  },

  /**
   * Procedural Digital Matrix Rain Canvas Backdrop (Rig Perk)
   * @param {boolean} enable
   */
  _toggleMatrixRain(enable) {
    if (typeof document === 'undefined') return;

    let canvas = document.getElementById('battlestation-matrix-canvas');

    if (!enable) {
      if (this.matrixAnimId) {
        cancelAnimationFrame(this.matrixAnimId);
        this.matrixAnimId = null;
      }
      if (canvas && canvas.parentNode) {
        canvas.parentNode.removeChild(canvas);
      }
      return;
    }

    if (!canvas) {
      canvas = document.createElement('canvas');
      canvas.id = 'battlestation-matrix-canvas';
      canvas.className = 'battlestation-matrix-canvas';
      canvas.style.cssText = 'position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; pointer-events: none; z-index: 0; opacity: 0.12;';
      document.body.prepend(canvas);
    }

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    resize();

    const chars = '0123456789ABCDEF<>/{};*+=_!&^%#@~';
    const fontSize = 14;
    const columns = Math.floor(canvas.width / fontSize);
    const drops = new Array(columns).fill(1);

    const draw = () => {
      ctx.fillStyle = 'rgba(10, 15, 29, 0.1)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = '#10b981';
      ctx.font = `${fontSize}px monospace`;

      for (let i = 0; i < drops.length; i++) {
        const text = chars.charAt(Math.floor(Math.random() * chars.length));
        ctx.fillText(text, i * fontSize, drops[i] * fontSize);

        if (drops[i] * fontSize > canvas.height && Math.random() > 0.975) {
          drops[i] = 0;
        }
        drops[i]++;
      }

      this.matrixAnimId = requestAnimationFrame(draw);
    };

    if (this.matrixAnimId) cancelAnimationFrame(this.matrixAnimId);
    this.matrixAnimId = requestAnimationFrame(draw);
  }
};

if (typeof window !== 'undefined') {
  window.BattlestationEngine = BattlestationEngine;
}

/* --- End of js/battlestation-engine.js --- */

/* --- Start of js/memory-minigame.js --- */
/**
 * SyntaxArena Tactile Memory Pointer Minigames Engine (Feature 8)
 * Powers:
 * 1. Cable Connect ("Stack Master"): Drag-and-drop pointer wire routing
 * 2. Leak Patrol ("Heap Hunter"): Mark-and-sweep garbage collection & orphan deallocation
 * 3. Dereference Rush ("Segfault Defuser"): Rapid-fire memory hazard triage
 * Zero external libraries or runtime dependencies.
 */


var MemoryMinigameEngine = window.MemoryMinigameEngine = class MemoryMinigameEngine {
  constructor(options = {}) {
    this.cableLevels = options.cableLevels || CABLE_CONNECT_LEVELS || [];
    this.leakLevels = options.leakLevels || LEAK_PATROL_LEVELS || [];
    this.rushChallenges = options.rushChallenges || DEREFERENCE_RUSH_CHALLENGES || [];

    this.activeMode = 'cable_connect'; // 'cable_connect' | 'leak_patrol' | 'dereference_rush'
    this.currentLevelIndex = 0;

    // Independent score and streak tracking per minigame mode
    this.modeScores = {
      cable_connect: 0,
      leak_patrol: 0,
      dereference_rush: 0
    };
    this.modeStreaks = {
      cable_connect: 0,
      leak_patrol: 0,
      dereference_rush: 0
    };
    this.modeMaxStreaks = {
      cable_connect: 0,
      leak_patrol: 0,
      dereference_rush: 0
    };

    // Cable connect state
    this.userConnections = []; // Array of { from: string, to: string }
    this.activeDrag = null;    // { fromId, x, y }

    // Leak patrol state
    this.currentHeapBytes = 0;
    this.maxHeapCapacity = 1024;
    this.reclaimedBlockIds = new Set();
    this.uafCount = 0;

    // Dereference rush state
    this.rushIndex = 0;
    this.rushTimer = 12;
    this._rushTimerInterval = null;
    this.rushStats = { correct: 0, wrong: 0, segfaults: 0 };

    this.listeners = new Map();
  }

  // Backwards-compatible accessors for active mode
  get score() {
    return this.modeScores[this.activeMode] || 0;
  }
  set score(val) {
    this.modeScores[this.activeMode] = val;
  }

  get streak() {
    return this.modeStreaks[this.activeMode] || 0;
  }
  set streak(val) {
    this.modeStreaks[this.activeMode] = val;
  }

  get maxStreak() {
    return this.modeMaxStreaks[this.activeMode] || 0;
  }
  set maxStreak(val) {
    this.modeMaxStreaks[this.activeMode] = val;
  }

  get totalScore() {
    return (this.modeScores.cable_connect || 0) +
           (this.modeScores.leak_patrol || 0) +
           (this.modeScores.dereference_rush || 0);
  }

  // ==========================================
  // EVENT BUS SYSTEM
  // ==========================================
  on(event, callback) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event).push(callback);
    return () => this.off(event, callback);
  }

  off(event, callback) {
    if (!this.listeners.has(event)) return;
    const list = this.listeners.get(event).filter(fn => fn !== callback);
    this.listeners.set(event, list);
  }

  emit(event, data) {
    if (!this.listeners.has(event)) return;
    for (const fn of this.listeners.get(event)) {
      try {
        fn(data);
      } catch (err) {
        console.error(`[MemoryMinigameEngine] Error in listener for ${event}:`, err);
      }
    }
  }

  // ==========================================
  // MODE & LEVEL MANAGEMENT
  // ==========================================
  setMode(mode) {
    if (!['cable_connect', 'leak_patrol', 'dereference_rush'].includes(mode)) {
      throw new Error(`Invalid minigame mode: ${mode}`);
    }
    this.activeMode = mode;
    this.currentLevelIndex = 0;
    this._stopRushTimer();

    if (mode === 'cable_connect') {
      this.loadCableLevel(0);
    } else if (mode === 'leak_patrol') {
      this.loadLeakLevel(0);
    } else if (mode === 'dereference_rush') {
      this.startDereferenceRush();
    }

    this.emit('modeChanged', { mode });
  }

  // ==========================================
  // 1. CABLE CONNECT ("STACK MASTER")
  // ==========================================
  loadCableLevel(index = 0) {
    if (index < 0 || index >= this.cableLevels.length) {
      index = 0;
    }
    this.currentLevelIndex = index;
    this.userConnections = [];
    const level = this.getCurrentCableLevel();
    this.emit('cableLevelLoaded', { level, index });
    return level;
  }

  getCurrentCableLevel() {
    return this.cableLevels[this.currentLevelIndex] || null;
  }

  addConnection(fromId, toId) {
    if (!fromId || !toId || fromId === toId) return false;

    // Check if duplicate connection already exists (Item 8: bidirectional check)
    const exists = this.userConnections.some(c => (c.from === fromId && c.to === toId) || (c.from === toId && c.to === fromId));
    if (exists) return false;

    // Check how many connections this level requires from this specific source
    const level = this.getCurrentCableLevel();
    const reqs = level ? (level.requiredConnections || []) : [];
    const allowedFromCount = reqs.filter(r => r.from === fromId || r.to === fromId).length;
    const currentFromCount = this.userConnections.filter(c => c.from === fromId || c.to === fromId).length;

    // If source only allows 1 connection in this level (e.g. standard pointer), replace previous
    if (allowedFromCount <= 1 && currentFromCount >= 1) {
      this.userConnections = this.userConnections.filter(c => c.from !== fromId && c.to !== fromId);
    }

    this.userConnections.push({ from: fromId, to: toId });
    this.emit('cableConnected', { from: fromId, to: toId, connections: [...this.userConnections] });
    return true;
  }

  removeConnection(fromId, toId) {
    const beforeCount = this.userConnections.length;
    this.userConnections = this.userConnections.filter(c => !(c.from === fromId && c.to === toId));
    if (this.userConnections.length !== beforeCount) {
      this.emit('cableRemoved', { from: fromId, to: toId, connections: [...this.userConnections] });
      return true;
    }
    return false;
  }

  clearConnections() {
    this.userConnections = [];
    this.emit('cablesCleared', {});
  }

  validateCableWiring() {
    const level = this.getCurrentCableLevel();
    if (!level) return { valid: false, feedback: 'No active level.' };

    const reqs = level.requiredConnections || [];
    let correctCount = 0;
    let incorrectCount = 0;

    for (const userConn of this.userConnections) {
      // Support bidirectional port routing (Item 8): from->to OR to->from
      const match = reqs.some(r => 
        (r.from === userConn.from && r.to === userConn.to) ||
        (r.from === userConn.to && r.to === userConn.from)
      );
      if (match) {
        correctCount++;
      } else {
        incorrectCount++;
      }
    }

    const missingCount = reqs.length - correctCount;
    const isValid = correctCount === reqs.length && incorrectCount === 0;

    if (isValid) {
      this.modeStreaks.cable_connect++;
      if (this.modeStreaks.cable_connect > this.modeMaxStreaks.cable_connect) {
        this.modeMaxStreaks.cable_connect = this.modeStreaks.cable_connect;
      }
      const pts = level.xpReward + (this.modeStreaks.cable_connect * 25);
      this.modeScores.cable_connect += pts;
      this._awardProfileXP(pts);

      const result = {
        valid: true,
        scoreAwarded: pts,
        totalScore: this.modeScores.cable_connect,
        streak: this.modeStreaks.cable_connect,
        feedback: 'Pointer routing verified! All addresses match ground truth.'
      };
      this.emit('cableWiringValidated', result);
      return result;
    } else {
      this.modeStreaks.cable_connect = 0;
      let reason = 'Pointer wire configuration mismatch.';
      if (missingCount > 0 && incorrectCount > 0) {
        reason = `Missing ${missingCount} required wire(s) and detected ${incorrectCount} invalid route(s).`;
      } else if (missingCount > 0) {
        reason = `Still missing ${missingCount} required pointer connection(s).`;
      } else if (incorrectCount > 0) {
        reason = `Detected ${incorrectCount} erroneous pointer assignment(s). Check variable target types.`;
      }

      const result = {
        valid: false,
        missing: missingCount,
        incorrect: incorrectCount,
        feedback: reason
      };
      this.emit('cableWiringValidated', result);
      return result;
    }
  }

  // ==========================================
  // 2. LEAK PATROL ("HEAP HUNTER")
  // ==========================================
  loadLeakLevel(index = 0) {
    if (index < 0 || index >= this.leakLevels.length) {
      index = 0;
    }
    this.currentLevelIndex = index;
    this.reclaimedBlockIds.clear();
    this.uafCount = 0;

    const level = this.getCurrentLeakLevel();
    if (level) {
      this.currentHeapBytes = level.initialHeapBytes;
      this.maxHeapCapacity = level.maxHeapCapacity;
      this._computeReachability(level);
    }

    this.emit('leakLevelLoaded', { level, index });
    return level;
  }

  getCurrentLeakLevel() {
    return this.leakLevels[this.currentLevelIndex] || null;
  }

  /**
   * Mark and sweep reachability graph solver.
   * Traverses from stack roots through heap block references.
   * Any block not reached is marked as orphaned.
   */
  _computeReachability(level) {
    if (!level) return;
    const reachable = new Set();
    const roots = level.stackRoots || [];
    const blocksMap = new Map((level.heapBlocks || []).map(b => [b.id, b]));

    // Queue roots
    const queue = [];
    for (const root of roots) {
      if (root.pointsTo && blocksMap.has(root.pointsTo)) {
        queue.push(root.pointsTo);
        reachable.add(root.pointsTo);
      }
    }

    // BFS traversal
    while (queue.length > 0) {
      const curId = queue.shift();
      const block = blocksMap.get(curId);
      if (block && block.references) {
        for (const childId of block.references) {
          if (blocksMap.has(childId) && !reachable.has(childId)) {
            reachable.add(childId);
            queue.push(childId);
          }
        }
      }
    }

    // Mark blocks
    for (const block of level.heapBlocks || []) {
      block.isOrphaned = !reachable.has(block.id);
    }
  }

  /**
   * Attempt to deallocate/free a heap block.
   * If orphaned: safe reclamation (+150 PTS, frees heap space).
   * If reachable: Use-After-Free alert (-100 PTS penalty, streak reset).
   */
  attemptReclaimBlock(blockId) {
    const level = this.getCurrentLeakLevel();
    if (!level) return { success: false, feedback: 'No active leak level.' };

    if (this.reclaimedBlockIds.has(blockId)) {
      return { success: false, feedback: 'Block already deallocated.' };
    }

    const block = (level.heapBlocks || []).find(b => b.id === blockId);
    if (!block) return { success: false, feedback: 'Block not found.' };

    if (block.isOrphaned) {
      this.reclaimedBlockIds.add(blockId);
      this.currentHeapBytes = Math.max(0, this.currentHeapBytes - block.sizeBytes);
      this.modeStreaks.leak_patrol++;
      if (this.modeStreaks.leak_patrol > this.modeMaxStreaks.leak_patrol) {
        this.modeMaxStreaks.leak_patrol = this.modeStreaks.leak_patrol;
      }

      const pts = 150 + (this.modeStreaks.leak_patrol * 20);
      this.modeScores.leak_patrol += pts;
      this._awardProfileXP(pts);

      // Check if all target orphans collected
      const remainingOrphans = (level.orphansToReclaim || []).filter(id => !this.reclaimedBlockIds.has(id));
      const levelComplete = remainingOrphans.length === 0;

      const result = {
        success: true,
        blockId,
        bytesReclaimed: block.sizeBytes,
        currentHeapBytes: this.currentHeapBytes,
        maxHeapCapacity: this.maxHeapCapacity,
        scoreAwarded: pts,
        totalScore: this.modeScores.leak_patrol,
        streak: this.modeStreaks.leak_patrol,
        remainingOrphansCount: remainingOrphans.length,
        levelComplete,
        feedback: `Reclaimed ${block.sizeBytes}B orphaned memory at ${block.address}. Heap capacity relieved!`
      };

      this.emit('blockReclaimed', result);
      if (levelComplete) {
        this.emit('leakLevelCompleted', { level, score: this.modeScores.leak_patrol });
      }
      return result;
    } else {
      // Use After Free!
      this.uafCount++;
      this.modeStreaks.leak_patrol = 0;
      this.modeScores.leak_patrol = Math.max(0, this.modeScores.leak_patrol - 100);

      const result = {
        success: false,
        useAfterFree: true,
        blockId,
        address: block.address,
        totalScore: this.modeScores.leak_patrol,
        feedback: `🚨 CRITICAL USE-AFTER-FREE! Block at ${block.address} is still actively referenced by live code!`
      };

      this.emit('useAfterFreeTriggered', result);
      return result;
    }
  }

  // ==========================================
  // 3. DEREFERENCE RUSH ("SEGFAULT DEFUSER")
  // ==========================================
  startDereferenceRush() {
    this.rushIndex = 0;
    this.rushStats = { correct: 0, wrong: 0, segfaults: 0 };
    this.modeStreaks.dereference_rush = 0;
    this._nextRushChallenge();
  }

  _nextRushChallenge() {
    this._stopRushTimer();
    if (this.rushIndex >= this.rushChallenges.length) {
      this.emit('dereferenceRushCompleted', {
        stats: { ...this.rushStats },
        score: this.modeScores.dereference_rush,
        maxStreak: this.modeMaxStreaks.dereference_rush
      });
      return;
    }

    this.rushTimer = 12; // 12 seconds per hazard
    const challenge = this.rushChallenges[this.rushIndex];

    this._rushTimerInterval = setInterval(() => {
      this.rushTimer--;
      this.emit('rushTimerTick', { secondsRemaining: this.rushTimer });
      if (this.rushTimer <= 0) {
        this._stopRushTimer();
        this.submitRushAnswer('TIMEOUT');
      }
    }, 1000);

    this.emit('rushChallengeLoaded', {
      challenge,
      index: this.rushIndex,
      total: this.rushChallenges.length,
      secondsRemaining: this.rushTimer
    });
  }

  _stopRushTimer() {
    if (this._rushTimerInterval) {
      clearInterval(this._rushTimerInterval);
      this._rushTimerInterval = null;
    }
  }

  submitRushAnswer(chosenCategory) {
    this._stopRushTimer();
    const challenge = this.rushChallenges[this.rushIndex];
    if (!challenge) return null;

    // Flexible match: buffer overrun button matches both 'out_of_bounds' and 'wild_pointer'
    const isCorrect = chosenCategory === challenge.category ||
      (chosenCategory === 'out_of_bounds' && challenge.category === 'wild_pointer');

    let pts = 0;

    if (isCorrect) {
      this.modeStreaks.dereference_rush++;
      if (this.modeStreaks.dereference_rush > this.modeMaxStreaks.dereference_rush) {
        this.modeMaxStreaks.dereference_rush = this.modeStreaks.dereference_rush;
      }
      pts = 100 + (this.modeStreaks.dereference_rush * 25);
      this.modeScores.dereference_rush += pts;
      this.rushStats.correct++;
      this._awardProfileXP(pts);
    } else {
      this.modeStreaks.dereference_rush = 0;
      this.rushStats.wrong++;
      if (chosenCategory === 'safe_dereference' && challenge.category !== 'safe_dereference') {
        this.rushStats.segfaults++;
      }
    }

    const result = {
      isCorrect,
      chosenCategory,
      correctCategory: challenge.category,
      explanation: challenge.explanation,
      scoreAwarded: pts,
      totalScore: this.modeScores.dereference_rush,
      streak: this.modeStreaks.dereference_rush,
      stats: { ...this.rushStats }
    };

    this.emit('rushAnswerEvaluated', result);

    this.rushIndex++;
    return result;
  }

  proceedToNextRushChallenge() {
    // Item 11: Break 15 challenges into stages of 5 with sector intermission checkpoints
    if (this.rushIndex > 0 && this.rushIndex % 5 === 0 && this.rushIndex < this.rushChallenges.length && !this._rushStageCheckpointAcknowledged) {
      this._rushStageCheckpointAcknowledged = true;
      this.emit('rushStageCompleted', {
        stage: this.rushIndex / 5,
        totalStages: Math.ceil(this.rushChallenges.length / 5),
        nextIndex: this.rushIndex,
        score: this.modeScores.dereference_rush,
        stats: { ...this.rushStats }
      });
      return;
    }
    this._rushStageCheckpointAcknowledged = false;
    this._nextRushChallenge();
  }

  // ==========================================
  // PROFILE GAMIFICATION SYNC
  // ==========================================
  _awardProfileXP(pts) {
    if (typeof window !== 'undefined' && window.Profile && typeof window.Profile.addXP === 'function') {
      try {
        window.Profile.addXP(pts);
      } catch (_) {}
    }
  }
}

if (typeof window !== 'undefined') {
  window.MemoryMinigameEngine = MemoryMinigameEngine;
}

/* --- End of js/memory-minigame.js --- */

/* --- Start of js/analytics.js --- */
/**
 * SyntaxArena Learning Analytics & Performance Engine (Batch 7)
 * Pure, deterministic functions for topic mastery classification, language & difficulty
 * aggregations, historical trend tracking, and evidence-based learning recommendations.
 * Source of truth: docs/MVP_SPEC.md, docs/GAME_RULES.md, docs/ARCHITECTURE.md
 */

// =============================================================================
// 1. CONFIGURATION & CONSTANTS
// =============================================================================

var TOPIC_THRESHOLDS = window.TOPIC_THRESHOLDS = Object.freeze({
  STRONG: 80,          // >= 80% accuracy
  DEVELOPING: 50,      // 50% to 79.9% accuracy
  MIN_SAMPLE_SIZE: 2   // Requires >= 2 attempts to avoid 1/1 = 100% false mastery
});

var GRADE_THRESHOLDS = window.GRADE_THRESHOLDS = Object.freeze({
  S: 95,
  A: 85,
  B: 70,
  C: 50
});

var TOPIC_NAMES = window.TOPIC_NAMES = Object.freeze({
  data_structures: 'Data Structures & Collections',
  data_types: 'Data Types & Immutability',
  pointers: 'Pointer Arithmetic & Memory',
  memory: 'Memory Management & Allocation',
  references: 'Value vs Reference Semantics',
  control_flow: 'Control Flow & Conditionals',
  functions: 'Functions & Scope Binding',
  oop: 'Object-Oriented Programming',
  concurrency: 'Async & Threading',
  type_system: 'Type System & Type Conversions',
  syntax_semantics: 'Syntax & Operator Precedence',
  error_handling: 'Exception & Error Handling'
});

// =============================================================================
// 2. CORE STATISTICAL & AGGREGATION FUNCTIONS
// =============================================================================

var Analytics = window.Analytics = {
  TOPIC_THRESHOLDS,
  GRADE_THRESHOLDS,
  TOPIC_NAMES,

  /**
   * Safe accuracy percentage calculation.
   * Prevents division by zero and invalid inputs.
   *
   * @param {number} correct - Number of correct answers
   * @param {number} attempted - Total questions attempted
   * @returns {number} Integer between 0 and 100
   */
  calculateAccuracy(correct, attempted) {
    const c = Math.max(0, parseInt(correct, 10) || 0);
    const a = Math.max(0, parseInt(attempted, 10) || 0);
    if (a === 0) return 0;
    return Math.min(100, Math.max(0, Math.round((c / a) * 100)));
  },

  /**
   * Formats a technical topic identifier into a human-friendly title.
   * @param {string} topicKey
   * @returns {string}
   */
  formatTopicName(topicKey) {
    if (!topicKey || typeof topicKey !== 'string') return 'Core Programming Concepts';
    const clean = topicKey.trim().toLowerCase();
    if (TOPIC_NAMES[clean]) return TOPIC_NAMES[clean];
    return clean
      .split('_')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  },

  /**
   * Classify topic mastery based on accuracy and sample size.
   *
   * @param {number} accuracy - Percentage (0-100)
   * @param {number} attempts - Number of question attempts
   * @returns {'strong'|'developing'|'needs_practice'|'insufficient_data'}
   */
  classifyTopic(accuracy, attempts) {
    const att = Math.max(0, parseInt(attempts, 10) || 0);
    const acc = Math.max(0, Math.min(100, parseInt(accuracy, 10) || 0));

    if (att < TOPIC_THRESHOLDS.MIN_SAMPLE_SIZE) {
      return 'insufficient_data';
    }
    if (acc >= TOPIC_THRESHOLDS.STRONG) {
      return 'strong';
    }
    if (acc >= TOPIC_THRESHOLDS.DEVELOPING) {
      return 'developing';
    }
    return 'needs_practice';
  },

  /**
   * Evaluate stage performance grade and messaging.
   *
   * @param {number} accuracy - Accuracy percentage (0-100)
   * @param {boolean} [isGameOver=false] - True if Hardcore mode 0 hearts
   * @returns {{ grade: string, title: string, subtitle: string, badgeClass: string, colorVar: string }}
   */
  getGradeData(accuracy, isGameOver = false) {
    const acc = Math.max(0, Math.min(100, parseInt(accuracy, 10) || 0));

    if (isGameOver) {
      return {
        grade: 'TERM',
        title: 'Run Terminated',
        subtitle: 'Hearts depleted before stage completion. Score & XP committed.',
        badgeClass: 'badge-coral',
        colorVar: 'var(--color-danger)'
      };
    }

    if (acc >= GRADE_THRESHOLDS.S) {
      return {
        grade: 'S',
        title: 'Flawless Precision',
        subtitle: 'Outstanding code-tracing and syntactic mastery!',
        badgeClass: 'badge-emerald',
        colorVar: 'var(--color-primary)'
      };
    }
    if (acc >= GRADE_THRESHOLDS.A) {
      return {
        grade: 'A',
        title: 'High Dexterity',
        subtitle: 'Strong conceptual comprehension with minimal mistakes.',
        badgeClass: 'badge-emerald',
        colorVar: 'var(--color-primary)'
      };
    }
    if (acc >= GRADE_THRESHOLDS.B) {
      return {
        grade: 'B',
        title: 'Solid Understanding',
        subtitle: 'Good execution insight; review edge cases to reach perfection.',
        badgeClass: 'badge-cyan',
        colorVar: 'var(--color-success)'
      };
    }
    if (acc >= GRADE_THRESHOLDS.C) {
      return {
        grade: 'C',
        title: 'Developing Grasp',
        subtitle: 'Passable execution understanding; review missed questions.',
        badgeClass: 'badge-amber',
        colorVar: 'var(--color-warning)'
      };
    }
    return {
      grade: 'F',
      title: 'Needs Reinforcement',
      subtitle: 'Multiple core misconceptions detected. Recommended: Review explanations.',
      badgeClass: 'badge-coral',
      colorVar: 'var(--color-danger)'
    };
  },

  /**
   * Group question outcome records by topic and calculate per-topic statistics.
   *
   * @param {Array<object>} results - Array of question outcome records
   * @returns {Array<object>} Sorted list of topic performance objects
   */
  groupResultsByTopic(results) {
    if (!Array.isArray(results) || results.length === 0) {
      return [];
    }

    const topicMap = new Map();

    results.forEach((item, index) => {
      if (!item || typeof item !== 'object') return;
      const topicKey = (item.topic || 'general').trim().toLowerCase();
      const isCorrect = Boolean(item.isCorrect || item.correct);

      if (!topicMap.has(topicKey)) {
        topicMap.set(topicKey, {
          topic: topicKey,
          topicName: this.formatTopicName(topicKey),
          attempted: 0,
          correct: 0,
          incorrect: 0,
          subtopics: new Set(),
          questionIds: []
        });
      }

      const entry = topicMap.get(topicKey);
      entry.attempted++;
      if (isCorrect) {
        entry.correct++;
      } else {
        entry.incorrect++;
      }
      if (item.subtopic) {
        entry.subtopics.add(item.subtopic);
      }
      if (item.questionId || item.id) {
        entry.questionIds.push(item.questionId || item.id);
      }
    });

    const output = [];
    topicMap.forEach(data => {
      const accuracy = this.calculateAccuracy(data.correct, data.attempted);
      const classification = this.classifyTopic(accuracy, data.attempted);

      output.push({
        topic: data.topic,
        topicName: data.topicName,
        attempted: data.attempted,
        correct: data.correct,
        incorrect: data.incorrect,
        accuracy,
        classification,
        subtopics: Array.from(data.subtopics),
        questionIds: data.questionIds
      });
    });

    // Sort: lowest accuracy first to highlight weaknesses, then by volume
    return output.sort((a, b) => {
      if (a.accuracy !== b.accuracy) return a.accuracy - b.accuracy;
      return b.attempted - a.attempted;
    });
  },

  /**
   * Aggregate career performance for a specific programming language.
   *
   * @param {Array<object>} sessions - All completed historical session records
   * @param {'python'|'c'|'cpp'|'java'} language - Target language
   * @returns {object} Aggregated language performance summary
   */
  aggregateLanguageStats(sessions, language) {
    const lang = (language || 'python').toLowerCase().trim();
    const safeSessions = Array.isArray(sessions) ? sessions : [];
    const matched = safeSessions.filter(s => s && (s.language || '').toLowerCase().trim() === lang);

    if (matched.length === 0) {
      return {
        language: lang,
        hasData: false,
        totalSessions: 0,
        completedSessions: 0,
        questionsAttempted: 0,
        questionsCorrect: 0,
        questionsIncorrect: 0,
        accuracy: 0,
        bestScore: 0,
        totalScore: 0,
        strongTopics: [],
        weakTopics: []
      };
    }

    let totalSessions = matched.length;
    let completedSessions = 0;
    let questionsAttempted = 0;
    let questionsCorrect = 0;
    let bestScore = 0;
    let totalScore = 0;
    const allResults = [];

    matched.forEach(s => {
      const isRetry = s.mode === 'retry_missed' || Boolean(s.isRetryMissed);
      if (s.isCompleted !== false) completedSessions++;
      const att = parseInt(s.questionsAttempted, 10) || 0;
      const corr = parseInt(s.questionsCorrect, 10) || 0;
      const sc = parseInt(s.totalScore || s.score, 10) || 0;

      if (!isRetry) {
        questionsAttempted += att;
        questionsCorrect += corr;
      }
      totalScore += sc;
      if (sc > bestScore) bestScore = sc;

      if (Array.isArray(s.results)) {
        allResults.push(...s.results);
      }
    });

    const accuracy = this.calculateAccuracy(questionsCorrect, questionsAttempted);
    const topicBreakdown = this.groupResultsByTopic(allResults);

    const strongTopics = topicBreakdown.filter(t => t.classification === 'strong');
    const weakTopics = topicBreakdown.filter(t => t.classification === 'needs_practice');

    return {
      language: lang,
      hasData: true,
      totalSessions,
      completedSessions,
      questionsAttempted,
      questionsCorrect,
      questionsIncorrect: Math.max(0, questionsAttempted - questionsCorrect),
      accuracy,
      bestScore,
      totalScore,
      topicBreakdown,
      strongTopics,
      weakTopics
    };
  },

  /**
   * Aggregate career performance for a specific difficulty tier.
   *
   * @param {Array<object>} sessions - Historical session records
   * @param {'beginner'|'intermediate'|'expert'} difficulty - Target tier
   * @returns {object} Tier metrics summary
   */
  aggregateDifficultyStats(sessions, difficulty) {
    const diff = (difficulty || 'beginner').toLowerCase().trim();
    const safeSessions = Array.isArray(sessions) ? sessions : [];
    const matched = safeSessions.filter(s => s && (s.difficulty || '').toLowerCase().trim() === diff);

    if (matched.length === 0) {
      return {
        difficulty: diff,
        hasData: false,
        totalSessions: 0,
        completedSessions: 0,
        questionsAttempted: 0,
        questionsCorrect: 0,
        accuracy: 0,
        avgScore: 0,
        bestScore: 0
      };
    }

    let totalSessions = matched.length;
    let completedSessions = 0;
    let questionsAttempted = 0;
    let questionsCorrect = 0;
    let bestScore = 0;
    let totalScore = 0;

    matched.forEach(s => {
      const isRetry = s.mode === 'retry_missed' || Boolean(s.isRetryMissed);
      if (s.isCompleted !== false) completedSessions++;
      const att = parseInt(s.questionsAttempted, 10) || 0;
      const corr = parseInt(s.questionsCorrect, 10) || 0;
      const sc = parseInt(s.totalScore || s.score, 10) || 0;

      if (!isRetry) {
        questionsAttempted += att;
        questionsCorrect += corr;
      }
      totalScore += sc;
      if (sc > bestScore) bestScore = sc;
    });

    const accuracy = this.calculateAccuracy(questionsCorrect, questionsAttempted);
    const avgScore = completedSessions > 0 ? Math.round(totalScore / completedSessions) : 0;

    return {
      difficulty: diff,
      hasData: true,
      totalSessions,
      completedSessions,
      questionsAttempted,
      questionsCorrect,
      questionsIncorrect: Math.max(0, questionsAttempted - questionsCorrect),
      accuracy,
      avgScore,
      bestScore
    };
  },

  /**
   * Calculate chronological trend metrics across historical sessions.
   *
   * @param {Array<object>} sessions - Historical session records
   * @param {number} [maxEntries=10] - Number of recent records to analyze
   * @returns {{ points: Array<object>, trend: 'improving'|'declining'|'steady'|'neutral', avgAccuracy: number }}
   */
  calculateHistoricalTrend(sessions, maxEntries = 10) {
    if (!Array.isArray(sessions) || sessions.length === 0) {
      return {
        points: [],
        trend: 'neutral',
        avgAccuracy: 0
      };
    }

    // Filter valid completed or attempted sessions and sort chronologically (oldest to newest)
    const valid = sessions
      .filter(s => s && typeof s === 'object' && (s.questionsAttempted > 0 || s.totalQuestions > 0))
      .sort((a, b) => (a.timestamp || a.startTime || 0) - (b.timestamp || b.startTime || 0));

    const slice = valid.slice(-maxEntries);
    if (slice.length === 0) {
      return { points: [], trend: 'neutral', avgAccuracy: 0 };
    }

    let sumAcc = 0;
    const points = slice.map((s, idx) => {
      const att = s.questionsAttempted || s.totalQuestions || 0;
      const corr = s.questionsCorrect !== undefined ? s.questionsCorrect : (s.correctCount || 0);
      const acc = s.accuracy !== undefined ? s.accuracy : this.calculateAccuracy(corr, att);
      sumAcc += acc;

      return {
        index: idx + 1,
        sessionId: s.sessionId || s.id || `sess_${idx}`,
        date: s.timestamp ? new Date(s.timestamp).toLocaleDateString() : 'Recent',
        language: s.language || 'python',
        difficulty: s.difficulty || 'beginner',
        score: s.totalScore || s.score || 0,
        accuracy: acc,
        isCompleted: s.isCompleted !== false
      };
    });

    const avgAccuracy = Math.round(sumAcc / points.length);

    // Determine slope / trend
    let trend = 'steady';
    if (points.length >= 3) {
      const firstHalf = points.slice(0, Math.floor(points.length / 2));
      const secondHalf = points.slice(Math.floor(points.length / 2));

      const avg1 = firstHalf.reduce((sum, p) => sum + p.accuracy, 0) / firstHalf.length;
      const avg2 = secondHalf.reduce((sum, p) => sum + p.accuracy, 0) / secondHalf.length;

      const diff = avg2 - avg1;
      if (diff >= 5) trend = 'improving';
      else if (diff <= -5) trend = 'declining';
      else trend = 'steady';
    }

    return {
      points,
      trend,
      avgAccuracy
    };
  },

  /**
   * Deterministic learning recommendations generator.
   * Traceable, evidence-backed next steps without external APIs or fabricated AI.
   *
   * @param {object} sessionSummary - The completed or inspected session summary
   * @param {object} profile - Active player profile
   * @returns {Array<object>} Prioritized list of actionable recommendations
   */
  generateRecommendations(sessionSummary, profile = {}) {
    const recs = [];
    if (!sessionSummary || typeof sessionSummary !== 'object') {
      return [
        {
          id: 'rec_get_started',
          type: 'general',
          title: 'Enter the Challenge Arena',
          reason: 'Complete your first programming challenge session to unlock personalized analytics.',
          actionLabel: 'Launch Beginner Arena',
          actionUrl: 'game.html?lang=python&diff=beginner&mode=campaign'
        }
      ];
    }

    const lang = (sessionSummary.language || 'python').toLowerCase();
    const diff = (sessionSummary.difficulty || 'beginner').toLowerCase();
    const accuracy = sessionSummary.accuracy !== undefined
      ? sessionSummary.accuracy
      : this.calculateAccuracy(sessionSummary.questionsCorrect, sessionSummary.questionsAttempted);

    const results = Array.isArray(sessionSummary.results) ? sessionSummary.results : [];
    const topicBreakdown = this.groupResultsByTopic(results);
    const playerLevel = (profile && profile.level) || 1;

    // 1. Weak Topic Recommendation (Immediate pedagogical focus)
    const weakTopic = topicBreakdown.find(t => t.classification === 'needs_practice');
    if (weakTopic) {
      recs.push({
        id: `rec_topic_${weakTopic.topic}`,
        type: 'weak_topic',
        priority: 1,
        title: `Reinforce: ${weakTopic.topicName}`,
        reason: `Accuracy was ${weakTopic.accuracy}% (${weakTopic.correct}/${weakTopic.attempted} correct) on this topic during your run.`,
        actionLabel: `Practice ${weakTopic.topicName}`,
        actionUrl: `game.html?lang=${lang}&diff=${diff}&topic=${encodeURIComponent(weakTopic.topic)}&mode=practice`
      });
    }

    // 2. Retry Missed Questions Recommendation
    const missedCount = sessionSummary.incorrectCount !== undefined
      ? sessionSummary.incorrectCount
      : (sessionSummary.questionsAttempted - sessionSummary.questionsCorrect);

    if (missedCount > 0) {
      recs.push({
        id: 'rec_retry_missed',
        type: 'retry_missed',
        priority: 2,
        title: `Retry ${missedCount} Missed Question${missedCount > 1 ? 's' : ''}`,
        reason: 'Consolidate understanding by re-attempting concepts you missed with step-by-step explanations.',
        actionLabel: 'Launch Retry Session',
        actionUrl: `game.html?lang=${lang}&diff=${diff}&mode=retry_missed`
      });
    }

    // 3. Tier Advancement Recommendation
    if (accuracy >= 85 && (sessionSummary.questionsAttempted || 0) >= 4) {
      if (diff === 'beginner') {
        recs.push({
          id: 'rec_advance_intermediate',
          type: 'tier_advance',
          priority: 3,
          title: `Advance to Intermediate ${this.formatTopicName(lang)}`,
          reason: `High precision (${accuracy}%) on Beginner! You are ready for pointer aliasing, closures, and object lifetimes.`,
          actionLabel: 'Launch Intermediate Track',
          actionUrl: `game.html?lang=${lang}&diff=intermediate&mode=campaign`
        });
      } else if (diff === 'intermediate') {
        recs.push({
          id: 'rec_advance_expert',
          type: 'tier_advance',
          priority: 3,
          title: `Challenge the Expert ${this.formatTopicName(lang)} Tier`,
          reason: `Formidable mastery (${accuracy}%) on Intermediate. Tackle edge-case semantics and compiler internals.`,
          actionLabel: 'Launch Expert Track',
          actionUrl: `game.html?lang=${lang}&diff=expert&mode=campaign`
        });
      }
    }

    // 4. Hardcore Mode Recommendation (Level 5+ unlocked)
    if (accuracy >= 90 && playerLevel >= 5 && sessionSummary.mode !== 'hardcore') {
      recs.push({
        id: 'rec_try_hardcore',
        type: 'challenge_mode',
        priority: 4,
        title: 'Test Your Mastery in Hardcore Mode',
        reason: 'You have proven high accuracy and reached Level 5+. Test your nerves with 3 hearts and no hints!',
        actionLabel: 'Enter Hardcore Arena',
        actionUrl: `game.html?lang=${lang}&diff=${diff}&mode=hardcore`
      });
    }

    // 5. Polyglot Track Exploration
    const campaign = (profile && profile.campaign) || {};
    const unplayedLangs = ['python', 'c', 'cpp', 'java', 'cyber', 'javascript', 'rust', 'sql', 'typescript', 'go', 'html', 'asm'].filter(l => {
      const camp = campaign[l];
      return !camp || (camp.beginnerStars === 0 && camp.unlockedTier === 'beginner');
    });

    if (unplayedLangs.length > 0 && recs.length < 3) {
      const nextLang = unplayedLangs[0];
      const titles = {
        python: 'Python 3',
        c: 'C (C99)',
        cpp: 'C++',
        java: 'Java',
        cyber: 'Cyber & Linux',
        javascript: 'JavaScript',
        rust: 'Rust',
        sql: 'SQL',
        typescript: 'TypeScript',
        go: 'Go (Golang)',
        html: 'HTML5 & Modern CSS',
        asm: 'Assembly & Reverse Engineering'
      };
      const langTitle = titles[nextLang] || nextLang.toUpperCase();
      recs.push({
        id: `rec_explore_${nextLang}`,
        type: 'polyglot',
        priority: 5,
        title: `Explore the ${langTitle} Arena Track`,
        reason: `Broaden your systems insight by tackling language-specific execution mechanics in ${langTitle}.`,
        actionLabel: `Begin ${langTitle} Track`,
        actionUrl: `game.html?lang=${nextLang}&diff=beginner&mode=campaign`
      });
    }

    // Ensure at least 1 helpful recommendation
    if (recs.length === 0) {
      recs.push({
        id: 'rec_general_play',
        type: 'general',
        priority: 6,
        title: 'Run Stage Again',
        reason: 'Solid session performance! Play again to improve your score and speed multipliers.',
        actionLabel: 'Replay Challenge Track',
        actionUrl: `game.html?lang=${lang}&diff=${diff}&mode=campaign`
      });
    }

    // Sort by priority and cap at 3 recommendations
    return recs.sort((a, b) => a.priority - b.priority).slice(0, 3);
  }
};

